<section class="glass panel"><div class="portal-heading"><h2>Your achievements</h2><span class="portal-status">Level <?php echo $rewards['level']; ?></span></div><div class="portal-xp"><strong><?php echo $rewards['xp']; ?> XP</strong><progress max="100" value="<?php echo $rewards['progress']; ?>" aria-label="Progress to next level"></progress><span><?php echo 100-$rewards['progress']; ?> XP to level <?php echo $rewards['level']+1; ?></span></div><p class="muted">Each classroom quiz earns 20 completion XP plus up to 10 accuracy XP from your best result. Practice earns 10 XP per day. Retrying improves your best reward instead of duplicating it.</p><div class="portal-badges"><?php foreach ($rewards['badges'] as $badge): ?><article class="portal-badge <?php echo $badge['earned']?'is-earned':'is-locked'; ?>"><span class="portal-badge-art badge-cell-<?php echo $badge['cell']; ?>" aria-hidden="true"></span><h3><?php echo esc($badge['name']); ?></h3><p><?php echo esc($badge['description']); ?></p><span class="portal-status"><?php echo $badge['earned']?'Earned':'Keep going'; ?></span></article><?php endforeach; ?></div></section>
<section class="glass panel"><h2>Classroom leaderboards</h2><form method="get" class="portal-filters"><input type="hidden" name="view" value="achievements"><label><span>Ranking period</span><select name="ranking"><option value="all">All-time quiz points</option><option value="week" <?php echo ($_GET['ranking'] ?? '')==='week'?'selected':''; ?>>This week's classroom XP</option></select></label><button class="button button-secondary">View rankings</button></form><p class="muted">Existing classroom score rankings use your best quiz results. Practice XP stays separate from academic grades and these rankings.</p><?php foreach ($classes as $class): ?><details class="portal-ranking"><summary><?php echo esc($class['subject']); ?></summary><div class="portal-table-scroll"><table class="portal-table"><thead><tr><th>Rank</th><th>Student</th><th><?php echo ($_GET['ranking'] ?? '')==='week'?'Weekly XP':'Points'; ?></th><th>Accuracy</th></tr></thead><tbody><?php foreach (array_slice(($_GET['ranking'] ?? '')==='week' ? portal_weekly_leaderboard(classroom_students($class),classroom_attempts((int)$class['id'])) : classroom_leaderboard($class),0,10) as $rank): ?><tr <?php echo (int)$rank['student']['id']===(int)$user['id']?'class="is-self"':''; ?>><td><?php echo (int)$rank['rank']; ?></td><th><?php echo esc($rank['student']['name']); ?><?php echo (int)$rank['student']['id']===(int)$user['id']?' (you)':''; ?></th><td><?php echo (int)$rank['total_score']; ?></td><td><?php echo esc((string)$rank['average_percent']); ?>%</td></tr><?php endforeach; ?></tbody></table></div><a href="/QuizWeb/classroom.php?id=<?php echo (int)$class['id']; ?>">Open classroom</a></details><?php endforeach; if (!$classes): ?><p class="muted">Join a classroom to participate.</p><?php endif; ?></section>
